 {const fk=ks.filter(d=>eat(D0(d)).k>0);if(fk.length>=2){const ap=avg(fk.map(d=>eat(D0(d)).p));a(ap>=c.pro*.85?'good':'tip',`Protein averages ${Math.round(ap)} g on days you log food, against a ${c.pro} g target.`,'food','food')}}
