function coachData(){const dayRows=days(60).map(k=>({date:k,sleep:sleepK(k),study:stuH(k),protein:eat(D0(k)).p})),mistBySubject={};live(S.mist).forEach(m=>{const u=U[m.unit];if(u)mistBySubject[u.l1]=(mistBySubject[u.l1]||0)+1});return Desk.coach({prog:S.prog,units:SYL.units,byId:U,today:L(),exam:S.cfg.exam,dayRows,sessions:live(S.sess),planOpen:allPlan().filter(x=>!x.del&&!x.done&&x.day<L()).length,weight:Desk.weightForecast(Object.keys(S.days).map(date=>({date,kg:+S.days[date].wt})).filter(x=>x.kg>0),S.cfg.wt),weightGoal:S.cfg.wt,proTarget:S.cfg.pro,mistBySubject})}
function coachHTML(n){return coachData().slice(0,n||4).map(i=>`<div class="in ${i.t||'tip'}">${i.wait?'⏳ ':'✦ '}${esc(i.m)}</div>`).join('')}
// Desk notes: only cross-signal patterns that no other card already shows. No pattern, no card.
function deskNotes(){const o=[],first=Object.keys(S.days).filter(act).sort()[0];if(!first)return o;const ks=days(60).filter(k=>k>=first&&k<L());
 const lo=[],hi=[];ks.forEach(k=>{const sl=sleepK(k);if(sl==null)return;if(sl<6.5)lo.push(stuH(k));else if(sl>=7)hi.push(stuH(k))});
 if(lo.length>=3&&hi.length>=3){const a=avg(lo),b=avg(hi);if(b-a>=.75)o.push(`After nights under 6.5 h you study ${a.toFixed(1)} h on average. After 7 h or more it is ${b.toFixed(1)} h.`)}
 const dw=[[],[],[],[],[],[],[]];ks.forEach(k=>dw[wdi(k)].push(stuH(k)));
 if(dw.every(a=>a.length>=4)){const m=dw.map(avg),mx=m.indexOf(Math.max(...m)),mn=m.indexOf(Math.min(...m));if(m[mx]-m[mn]>=1.5)o.push(`${DN[mx]} is your strongest study day (${m[mx].toFixed(1)} h on average) and ${DN[mn]} your weakest (${m[mn].toFixed(1)} h).`)}
 const last={};live(S.sess).forEach(x=>{if(x.unit&&U[x.unit]){const l=U[x.unit].l1;if(!last[l]||x.date>last[l])last[l]=x.date}});
 const old=Object.keys(last).map(l=>[l,Math.round((new Date(L())-new Date(last[l]))/864e5)]).filter(x=>x[1]>=10).sort((a,b)=>b[1]-a[1]);
 if(old.length&&Object.values(last).some(d=>d>=add(L(),-4)))o.push(`${old[0][0]} was last studied ${old[0][1]} days ago, while other subjects got time this week.`);
 return o.slice(0,3)}
const cNotes=()=>{const n=deskNotes();return n.length?card('notes','Desk notes','Only patterns worth acting on','',n.map(t=>`<div class="in tip">${esc(t)}</div>`).join('')):''};
// Quick log: one window, three boxes. Each box holds the controls of one kind.
const RUN='<svg class="run" viewBox="0 0 48 48" width="52" height="52" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="30" cy="9" r="3.5" fill="currentColor" stroke="none"/><path d="M27 15l-3 12"/><g class="ar a"><path d="M27 17l8 4"/></g><g class="ar b"><path d="M27 17l-7 3"/></g><g class="lg a"><path d="M24 27l7 9"/></g><g class="lg b"><path d="M24 27l-7 9"/></g><path class="gr" d="M4 44h40" stroke-dasharray="4 6" stroke-width="2" opacity=".45"/></svg>';
const qlog=x=>{const{k,d,c,wat}=x,sl=sleepK(k),pb=D0(add(k,-1)).bed,mt=Math.min(1,wat/2500),sp=Math.min(1,(d.steps||0)/c.steps);
 return `<section id="quicklog"><div class="ch"><div><h3>Quick log</h3><small>Tap, do not type. Everything updates live.</small></div>${go('dashboard/steps','Charts')}</div><div class="qgrid">
 <div class="qb"><div class="qh"><b>Sleep</b><span class="qi">☾</span></div><div class="qf"><div><label>Bed time (today)</label><input type="time" value="${d.bed||''}" data-f="bed"></div><div><label>Wake time (today)</label><input type="time" value="${d.wake||''}" data-f="wake"></div></div><small>${sl!=null?'Last night: <b>'+sl.toFixed(1)+' h</b> (bed '+pb+' yesterday, up '+d.wake+')':!d.wake?'Log your wake time to get last night’s sleep. Log bed time on the day you go to bed.':'No bed time was logged yesterday, so last night’s sleep cannot be worked out.'}</small></div>
 <div class="qb"><div class="qh"><b>Steps</b><small>goal ${c.steps}</small></div><div class="qrun">${RUN}<div class="qf1"><input type="number" min="0" value="${d.steps||''}" data-f="steps" placeholder="0" aria-label="Steps today"><button data-a="steps">+1000</button></div></div><div class="wm"><i style="width:${sp*100}%"></i></div></div>
 <div class="qb"><div class="qh"><b>Water</b><small>${wat} ml today</small></div><div class="qwat"><span class="qbot">${bot(mt)}</span><div class="row"><button data-a="water" data-v="500">+ ½ L</button><button data-a="water" data-v="1000">+ 1 L</button><button data-a="water" data-v="-250">− 250 ml</button></div></div><div class="wm"><i style="width:${mt*100}%"></i></div></div></div></section>`};
// Daily commitments: items come from the weekly plan and can be added manually.
const allPlan=()=>S.plan=S.plan||[],pWeek=k=>Desk.weekStart(k,S.cfg.wk),weekItems=k=>allPlan().filter(x=>!x.del&&x.week==pWeek(k)),todayItems=()=>{const k=L(),base=weekItems(k).filter(x=>x.day==k),carry=allPlan().filter(x=>!x.del&&!x.done&&x.day<k&&x.day>=add(k,-14));return [...carry,...base].filter(x=>!x.done)};
