const stageChoices=(prefix,paper)=>`<div class="row"><button class="chip ${paper=='P'?'p':''}" data-a="cPaper" data-v="P" data-cstep="${prefix}">Prelims</button><button class="chip ${paper=='M'?'p':''}" data-a="cPaper" data-v="M" data-cstep="${prefix}">Mains</button></div>`;
const tagSelectHTML=(id,prefix)=>{const paper=CASC[prefix+':paper']||S.lastPaper||syP,vals=CASC[prefix+':'+paper]||[],options=[['d','Study'],['q','PYQs'],...(paper=='P'?[['mc','MCQs']]:[['aw','Answer writing']]),['r1','Revision 1'],['p2',paper=='P'?'MCQs 2':'Answer writing 2'],['r2','Revision 2']];return `<select id="${id}">${options.map(x=>`<option value="${x[0]}" ${S.lastTag==x[0]?'selected':''}>${x[1]}</option>`).join('')}</select>`};
function cascadeHTML(prefix,unit,emptyStart){const paper=CASC[prefix+':paper']||(unit&&U[unit]?U[unit].paper:S.lastPaper||syP),chosen=unit&&U[unit]?unit:(CASC[prefix+':unit']||''),picked=U[chosen],term=CASC[prefix+':query']||'';return `${stageChoices(prefix,paper)}<div class="unit-picker" data-cascade="${prefix}" data-paper="${paper}" data-unit="${chosen}"><label class="sr-only" for="${prefix}search">Search syllabus microtopics</label><input id="${prefix}search" type="search" data-unit-search="${prefix}" value="${esc(term)}" placeholder="Search syllabus microtopics" autocomplete="off"><div class="unit-results" data-results="${prefix}">${unitResultsHTML(prefix,paper,term)}</div>${picked?`<div class="unit-selected"><span><small>${esc(picked.id)}</small> ${esc(picked.text)}<em>${esc(picked.l1)} › ${esc(picked.l2)} › ${esc(picked.l3)}</em></span><button type="button" data-a="unitClear" data-v="${prefix}" title="Clear selection" aria-label="Clear selection">×</button></div>`:''}</div>`}
