const unitResultsHTML=(prefix,paper,term)=>{const words=term.toLowerCase().trim().split(/\s+/).filter(Boolean);if(!words.length)return'';const hits=SYL.units.filter(u=>u.paper==paper&&words.every(w=>(u.id+' '+u.text+' '+u.l1+' '+u.l2+' '+u.l3).toLowerCase().includes(w))).slice(0,12);return `<div class="unit-dropdown">${hits.map(u=>`<button type="button" data-a="unitPick" data-v="${esc(u.id)}" data-prefix="${prefix}"><span><b>${esc(u.text)}</b><small>${esc(u.id)} · ${esc(u.l1)} › ${esc(u.l2)} › ${esc(u.l3)}</small></span><i>↵</i></button>`).join('')||'<small class="unit-no-results">No matching microtopics</small>'}</div>`};
